def read_rows(path):
    with open(path) as f:          # every open IS inside a with
        for line in f:
            yield parse(line)

def first_batch(path, n=100):
    rows = read_rows(path)
    batch = list(itertools.islice(rows, n))
    if not batch:
        return None                # empty tenant: abandon the generator
    PIPELINES[path] = rows         # keep remainder for the next phase
    return batch

for tenant_path in tenant_files:   # 3000 tenants tonight
    first_batch(tenant_path)
